+    var g = (gateCfg && typeof gateCfg === 'object') ? gateCfg : {};
+    return {
+        gateJobs: strArrayOr(g.gateJobs, DEFAULTS.gateJobs.slice()),
+        secretJobs: strArrayOr(g.secretJobs, DEFAULTS.secretJobs.slice())
+    };
