+    if (!Array.isArray(v)) return dflt;
+    var out = [];
+    for (var i = 0; i < v.length; i++) {
+        if (typeof v[i] === 'string' && v[i]) out.push(v[i]);
+    }
+    return out.length ? out : dflt;
+}
+
+function intOr(v, dflt) {
+    return (typeof v === 'number' && isFinite(v) && v > 0) ? Math.floor(v) : dflt;
+}
