+        baseBranch: strOr(section.baseBranch, DEFAULTS.baseBranch),
+        titlePrefix: strOr(section.titlePrefix, DEFAULTS.titlePrefix),
+        carryLabels: strArrayOr(section.carryLabels, DEFAULTS.carryLabels.slice()),
