            maxGcBranches: 10
        },
        base: { owner: 'base', repo: 'repo', baseBranch: 'main' },
        source: { prNumber: 42, title: 'guest change', author: 'guestuser',
                  labels: ['po_accept'], headRepo: 'guestuser/fork', draft: false, state: 'OPEN' },
        headSha: 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',
        armEvent: { login: 'humanreviewer', createdAt: '2026-10-20T10:00:00Z' },
        machineLogins: ['sm-bot'],
        marker: null,
        branchExists: false,
        openTransplantPr: null,
        completionRentry: false
    }, o || {});
}
function stepsOf(op, seq) {
    return (seq.steps || []).filter(function (s) { return s.op === op; });
}

// ── What the REAL wiring writes on a conflict park ──────────────────────
// Fresh sequence: comment(armed marker) + create_ref + merge(409!) → then
// parkSteps posts a PLAIN parkComment (no machine marker). The newest
// machine marker on the source stays state:'armed'.
var armedMarker = mod.parseTransplantMarker([
    { body: mod.transplantMarkerComment({ state: 'armed', source: 42,
        head: 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', branch: 'ai/guest-42' }) },
    // parkSteps' comment — plain text, parked-head line, NO machine marker:
    { body: mod.parkComment(
        'merge conflict at transplant time — the fork head no longer merges clean into main',
        'Re-arm happens automatically when a human push changes the head (parked-head reset).',
        'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa') }
]);
console.log('== transport-produced marker after a conflict park ==');
console.log(JSON.stringify(armedMarker));

console.log('\n== [A] next MAIN-path tick after the conflict park, guest pushed a fixed head ==');
var a = mod.transplantSequence(baseInput({
    source: { prNumber: 42, title: 'guest change', author: 'guestuser',
              labels: ['po_accept', 'blocked'], headRepo: 'guestuser/fork', draft: false, state: 'OPEN' },
    marker: armedMarker,
    headSha: 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'  // the FIXED head
}));
console.log('decision=' + a.decision + ' reason=' + a.reason);
console.log('audit=' + a.audit);

console.log('\n== [B] the GC sweep sees the orphaned branch (no PR on it), probes the same marker ==');
var sweepEntry = { branch: 'ai/guest-42', prState: null, marker: armedMarker };
var sweepSteps = mod.gcSteps([sweepEntry]);
console.log('sweep step: ' + JSON.stringify(sweepSteps));
// ...and re-enters the action with completionRentry (the round-1 fix):
var b = mod.transplantSequence(baseInput({
    source: { prNumber: 42, title: '', author: '', labels: ['po_accept'],
              headRepo: null, draft: false, state: 'OPEN' },
    marker: armedMarker,
    headSha: 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',
    branchExists: true,
    completionRentry: true
}));
console.log('re-entry decision=' + b.decision + ' reason=' + b.reason);
console.log('re-entry merge step: ' + JSON.stringify(stepsOf('merge', b)));
console.log('=> re-entry re-merges the RECORDED (stale, conflicting) sha: ' +
    (stepsOf('merge', b)[0] || {}).headSha);

console.log('\n== [C] after a COMPLETED transplant, the guest reopens the source ==');
// The wiring never writes a state:"transplanted" marker (buildTransplantComment
// is plain text) — the newest machine marker is still the ARM marker:
var reopened = mod.transplantSequence(baseInput({
    marker: armedMarker,          // ← what the transport really leaves behind
    branchExists: false,          // ← merged + GC'd (AC7)
    openTransplantPr: null,
    headSha: 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'
}));
console.log('decision=' + reopened.decision + ' reason=' + reopened.reason);
console.log('steps: ' + (reopened.steps || []).map(function (s) { return s.op; }).join(' → '));
console.log('=> duplicate transplant: ' + (reopened.decision === 'transplant' ? 'YES' : 'no'));

console.log('\n== [control] the same reopen WITH a hand-written transplanted marker ==');
var ctrl = mod.transplantSequence(baseInput({
    marker: { state: 'transplanted', source: 42, head: 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',
              branch: 'ai/guest-42', transplant: 99 },
    branchExists: false, openTransplantPr: null
}));
console.log('decision=' + ctrl.decision + ' reason=' + ctrl.reason);
